from pathlib import Path
p=Path(__file__).with_name('index.html')
s=p.read_text(encoding='utf-8')
marker='<!-- SPI-TV-20261124 -->'
if marker in s: raise SystemExit('Atualização já aplicada.')
patch=r'''<!-- SPI-TV-20261124 -->
<style>body.tv header,body.tv footer,body.tv .filters,body.tv nav,body.tv #adminActions,body.tv #settingsPanel,body.tv #staffPanel,body.tv .help{display:none!important}body.tv main{max-width:none;padding:12px}body.tv .tablewrap{max-height:75vh}body.tv .card b{font-size:clamp(26px,3vw,52px)}#tvExit{position:fixed;right:12px;bottom:12px;z-index:1000}</style>
<script>
(()=>{
const sumUnits=rs=>rs.reduce((n,r)=>n+(Number(r.units)||0),0);
const boxes=rs=>new Set(rs.filter(r=>r.box).map(r=>r.date+'|'+r.box)).size;
const oldRender=render;
render=function(){oldRender();if(!tab)return;const items=tab==='sep'?filtered('sep'):filtered('conf');if(tab==='sep'||tab==='conf')$('cards').insertAdjacentHTML('afterbegin',card(tab==='sep'?'Total de unidades separadas':'Total de caixas conferidas',fmt(tab==='sep'?sumUnits(items):boxes(items)),'No período selecionado'));};
const oldManagement=management;
management=function(sep,conf,st,ct){oldManagement(sep,conf,st,ct);if(tab!=='resumo'||role!=='admin')return;const el=$('management'),ds=dateRows(),[a,b]=bounds();if(ds.length!==1)return;const d=ds[0];const panels=[...el.querySelectorAll('.panel')];panels.find(p=>p.querySelector('h2')?.textContent.startsWith('Projeção de fechamento'))?.remove();const local=new Intl.DateTimeFormat('sv-SE',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date());const [today,clock]=local.split(' ');const [hh,mm]=clock.split(':').map(Number);const nowHour=d===today?hh+mm/60:nextDay(d)===today?24+hh+mm/60:d<today?48:0;const latest=rs=>Math.max(a,...rs.map(r=>r.hour+(r.minute==null?1:(r.minute+1)/60)));const cut=Math.min(b,nowHour,latest(sep),latest(conf));const panel=document.createElement('div');panel.className='panel';const time=h=>String(Math.floor(h)%24).padStart(2,'0')+':'+String(Math.round((h%1)*60)).padStart(2,'0')+(h>=24?' +1':'');if(cut<=a||!sep.length||!conf.length){panel.innerHTML='<h2>Projeção de fechamento</h2><p>Aguardando registros válidos das duas operações.</p>';el.prepend(panel);return;}const before=rs=>rs.filter(r=>r.hour+(r.minute??0)/60<cut);const S=sumUnits(before(sep)),C=sumUnits(before(conf)),ms=S/(cut-a),mc=C/(cut-a),rem=Math.max(0,b-cut);let rows='';for(let h=cut;h<b-1e-8;){const end=Math.min(b,Math.floor(h+1e-8)+1);rows+=`<tr><td>${time(h)}–${time(end)}</td><td>${fmt(Math.round(ms*(end-h)))}</td><td>${fmt(Math.round(mc*(end-h)))}</td></tr>`;h=end;}panel.innerHTML=`<h2>Projeção de fechamento • ${time(b)}</h2><p>Base comum até ${time(cut)} • média por hora corrida, sem desconto de pausas.</p><div class="cards">${card('Média separação/h',fmt(Math.round(ms)),'unidades')}${card('Média conferência/h',fmt(Math.round(mc)),'unidades')}${card('Separação projetada',fmt(Math.round(S+ms*rem)),'unidades')}${card('Conferência projetada',fmt(Math.round(C+mc*rem)),'unidades')}${card('Saldo gerado projetado',fmt(Math.round(S-C+(ms-mc)*rem)),'sem saldo inicial')}</div><table><thead><tr><th>Horário</th><th>Separação</th><th>Conferência</th></tr></thead><tbody>${rows}</tbody></table><p>Conferência superior à separação pode indicar saldo anterior ou divergência na base. Não representa necessariamente erro.</p>`;el.prepend(panel);};
const exit=document.createElement('button');exit.id='tvExit';exit.textContent='Sair do modo TV';exit.hidden=true;document.body.append(exit);exit.onclick=()=>{document.body.classList.remove('tv');exit.hidden=true;if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});};for(const [t,name] of [['sep','Separação'],['conf','Conferência']]){const b=document.createElement('button');b.className='choice';b.innerHTML='<strong>Modo TV • '+name+'</strong><small>Atualização automática a cada 30 segundos</small>';b.onclick=()=>{choose(t);document.body.classList.add('tv');exit.hidden=false;document.documentElement.requestFullscreen?.().catch(()=>{});};$('chooser').querySelector('.choices').append(b);}const tv=document.createElement('button');tv.textContent='Modo TV';tv.onclick=()=>{if(tab==='sep'||tab==='conf'){document.body.classList.add('tv');exit.hidden=false;document.documentElement.requestFullscreen?.().catch(()=>{});}else showApp();};$('dashboard').querySelector('nav').append(tv);render();
})();
</script>'''
assert '</body>' in s and 'function management(' in s and 'function render(' in s, 'Versão incompatível'
p.with_suffix('.html.bak').write_text(s,encoding='utf-8')
p.write_text(s.replace('</body>',patch+'\n</body>',1),encoding='utf-8')
print('index.html atualizado; backup em index.html.bak')
